package main

import (
	"strings"
	"testing"

	v1alpha1 "github.com/mudler/luet-k8s/pkg/apis/build.luet.io/v1alpha1"
	corev1 "k8s.io/api/core/v1"
)

func TestUsesBuildah(t *testing.T) {
	for _, tt := range []struct {
		backend string
		want    bool
	}{
		{BuildahBackend, true},
		// luet resolves the deprecated "img" backend to buildah, so from this
		// controller's point of view an img build IS a buildah build.
		{ImgBackend, true},
		{DockerBackend, false},
		{DockerSidecarBackend, false},
		{"", false},
	} {
		if got := usesBuildah(tt.backend); got != tt.want {
			t.Errorf("usesBuildah(%q) = %v, want %v", tt.backend, got, tt.want)
		}
	}
}

// A PackageBuild that names no backend must resolve to buildah, not img.
func TestGetBackendDefaultsToBuildah(t *testing.T) {
	opts := v1alpha1.BuildOptions{}
	if got := opts.GetBackend(); got != BuildahBackend {
		t.Errorf("GetBackend() with no backend set = %q, want %q", got, BuildahBackend)
	}
}

// An explicitly named backend is passed through unchanged, so luet emits its
// own deprecation warning for img and the user learns to migrate.
func TestGetBackendPassesThroughExplicitValues(t *testing.T) {
	for _, b := range []string{BuildahBackend, ImgBackend, DockerBackend} {
		opts := v1alpha1.BuildOptions{Backend: b}
		if got := opts.GetBackend(); got != b {
			t.Errorf("GetBackend() with Backend=%q = %q, want %q", b, got, b)
		}
	}
}

func buildWithCredentials(backend string) *v1alpha1.PackageBuild {
	return &v1alpha1.PackageBuild{
		Spec: v1alpha1.BuildSpec{
			Options: v1alpha1.BuildOptions{Backend: backend},
			RegistryCredentials: v1alpha1.RegistryCredentials{
				Enabled: true,
			},
		},
	}
}

func TestLuetCommandUsesBuildahLogin(t *testing.T) {
	for _, backend := range []string{BuildahBackend, ImgBackend, ""} {
		cmd := strings.Join(genLuetCommand(buildWithCredentials(backend)), " ")
		if !strings.Contains(cmd, "buildah login") {
			t.Errorf("backend %q: expected 'buildah login', got: %s", backend, cmd)
		}
		if strings.Contains(cmd, "img login") {
			t.Errorf("backend %q: found stale 'img login' in: %s", backend, cmd)
		}
	}
}

func TestCreateRepoCommandUsesBuildahLogin(t *testing.T) {
	for _, backend := range []string{BuildahBackend, ImgBackend, ""} {
		cmd := strings.Join(genCreateRepoCommand(buildWithCredentials(backend)), " ")
		if !strings.Contains(cmd, "buildah login") {
			t.Errorf("backend %q: expected 'buildah login', got: %s", backend, cmd)
		}
		if strings.Contains(cmd, "img login") {
			t.Errorf("backend %q: found stale 'img login' in: %s", backend, cmd)
		}
	}
}

// hasBackendArg reports whether cmd passes exactly "--backend want" as a
// standalone argument. The token has to be followed by a space or by the end
// of the string: a plain substring check would accept both an empty value
// (which collapses in the joined shell string and makes luet swallow the next
// flag as the backend name) and a longer value that merely starts with want,
// e.g. "docker-sidecar" matching "docker".
func hasBackendArg(cmd, want string) bool {
	prefix := "--backend " + want
	idx := strings.Index(cmd, prefix)
	if idx < 0 {
		return false
	}
	rest := cmd[idx+len(prefix):]
	return rest == "" || strings.HasPrefix(rest, " ")
}

// The resolved backend, not the raw field, has to reach the --backend flag of
// both command builders. An unset field means buildah, and docker-sidecar is a
// pod topology rather than a luet backend, so luet has to be told "docker".
func TestCommandsPassResolvedBackend(t *testing.T) {
	for _, tt := range []struct {
		name    string
		backend string
		want    string
	}{
		{"unset defaults to buildah", "", BuildahBackend},
		// img is passed through unchanged so luet emits its own deprecation warning.
		{"img passed through", ImgBackend, ImgBackend},
		{"buildah explicit", BuildahBackend, BuildahBackend},
		{"docker explicit", DockerBackend, DockerBackend},
		{"docker-sidecar resolves to docker", DockerSidecarBackend, DockerBackend},
	} {
		t.Run(tt.name, func(t *testing.T) {
			pb := &v1alpha1.PackageBuild{
				Spec: v1alpha1.BuildSpec{
					Options: v1alpha1.BuildOptions{Backend: tt.backend},
				},
			}

			build := strings.Join(genLuetCommand(pb), " ")
			if !hasBackendArg(build, tt.want) {
				t.Errorf("genLuetCommand with Backend=%q: expected %q, got: %s",
					tt.backend, "--backend "+tt.want, build)
			}

			createRepo := strings.Join(genCreateRepoCommand(pb), " ")
			if !hasBackendArg(createRepo, tt.want) {
				t.Errorf("genCreateRepoCommand with Backend=%q: expected %q, got: %s",
					tt.backend, "--backend "+tt.want, createRepo)
			}
		})
	}
}

func TestLuetCommandUsesDockerLoginForDocker(t *testing.T) {
	cmd := strings.Join(genLuetCommand(buildWithCredentials(DockerBackend)), " ")
	if !strings.Contains(cmd, "docker login") {
		t.Errorf("expected 'docker login', got: %s", cmd)
	}
	if strings.Contains(cmd, "buildah login") {
		t.Errorf("docker backend must not get buildah login: %s", cmd)
	}
}

func TestCreateRepoCommandUsesDockerLoginForDocker(t *testing.T) {
	cmd := strings.Join(genCreateRepoCommand(buildWithCredentials(DockerBackend)), " ")
	if !strings.Contains(cmd, "docker login") {
		t.Errorf("expected 'docker login', got: %s", cmd)
	}
	if strings.Contains(cmd, "buildah login") {
		t.Errorf("docker backend must not get buildah login: %s", cmd)
	}
}

func TestLuetCommandNoLoginWithoutCredentials(t *testing.T) {
	pb := &v1alpha1.PackageBuild{
		Spec: v1alpha1.BuildSpec{
			Options: v1alpha1.BuildOptions{Backend: BuildahBackend},
		},
	}
	cmd := strings.Join(genLuetCommand(pb), " ")
	if strings.Contains(cmd, "login") {
		t.Errorf("no credentials configured, expected no login: %s", cmd)
	}
}

func envValue(envs []corev1.EnvVar, name string) (string, bool) {
	for _, e := range envs {
		if e.Name == name {
			return e.Value, true
		}
	}
	return "", false
}

func TestBuildahRootlessEnv(t *testing.T) {
	// Includes "" because a resource naming no backend defaults to buildah and
	// must still get the rootless environment.
	for _, backend := range []string{BuildahBackend, ImgBackend, ""} {
		pb := &v1alpha1.PackageBuild{
			Spec: v1alpha1.BuildSpec{
				Options: v1alpha1.BuildOptions{Backend: backend},
			},
		}
		envs := genEnvVars(pb)

