// Rootless buildah calls unshare(CLONE_NEWUSER), which a default seccomp
// profile blocks. The pod's existing annotation form was removed in
// Kubernetes 1.25, so the GA SecurityContext field has to carry this.
func TestBuildContainerSeccompUnconfined(t *testing.T) {
	pb := &v1alpha1.PackageBuild{
