// the buildah backend. Anything conditional on buildah, such as the rootless
// environment or the registry login command, must use this rather than
// comparing against BuildahBackend alone, or an explicit img resource gets a
// buildah build without buildah's configuration.
func usesBuildah(backend string) bool {
	return backend == BuildahBackend || backend == ImgBackend
}
